// Hearthwood — blueprints: house templates, instant stamping with a cascade animation,
// guided building (translucent blueprint ghosts, staged), and the welcome lot.
//
// Blueprints are plain DATA (arrays of piece records, see ARCHITECTURE.md) generated by a few
// small helpers:
//   rect()        a rectangle of cell pieces (foundations, floors, decks)
//   walls()       a ring of wall-like edge pieces around a footprint, with openings per side
//   gableRoof()   the slopes of a symmetric gable roof (stacked with h, ridge along X or Z)
//   gableEnds()   the gables under it with the exact h / s / r the builder's autoGable would pick
//   run()         a straight run of edges (railings, fences, hedges, beams)
//   porch()       a front deck/porch: deck cells, railing with a gap + steps, optional posts & beams
// Footprints are given as boxes { x0, x1, z0, z1 } of inclusive cell coordinates. The FRONT of every
// house faces +Z (toward the default camera), so "front" edges are axis 'x' edges at z = z1 + 1.
// Every record is valid and owns a distinct slot; roof h and gable h/s/r equal what the builder's
// autoRoofHeight / autoGable compute, so guided players reproduce the blueprint exactly.
//
// Stages (guided mode & the stamp cascade) are derived from each record: foundation → ground-floor
// walls → porch → upper floor & stairs → upper walls → roof → gable ends → interior → garden. Each
// blueprint names its stages after what they hold (stageNamesFor: no "chimney" for a shed's roof).
//
// Runtime (init → { list, get, stamp, startGuided, stop, selectNext, welcome, active, update }):
//   stamp        adds everything in one undo batch, then pops pieces in by stage over ~2 s
//   guided mode  one ghost mesh per missing piece (a single merged geometry built with the blueprint
//                as neighbour context, so walls/roofs look finished), current stage bright, next faint
//   pictures     after boot, idle time-slices render a small picture per blueprint (bp.thumb) for the
//                UI cards, using clones of the scene's own lights so no new shaders are compiled

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/BufferGeometryUtils.js';
import { CELL, STEP, LEVEL_H, levelY, clamp } from './config.js';
import { getDef } from './catalog.js';
import { blueprintMat, mat } from './materials.js';
import { mergeByMaterial } from './world.js';

// ====================================================================== record helpers

/** A rectangle of cell pieces. */
function rect(t, x0, x1, z0, z1, y = 0, o = {}) {
  const out = [];
  for (let z = z0; z <= z1; z++) for (let x = x0; x <= x1; x++) out.push({ t, x, y, z, ...o });
  return out;
}

/** One cell piece. */
const at = (t, x, z, o = {}) => ({ t, x, y: 0, z, ...o });

/**
 * Edges along one side of a footprint box, ordered along +X (front/back) or +Z (left/right).
 * r points local +Z OUTWARD (shutters, doors and window boxes face the street).
 */
function edgesOf(b, side) {
  const out = [];
  if (side === 'front' || side === 'back') {
    const z = side === 'front' ? b.z1 + 1 : b.z0;
    for (let x = b.x0; x <= b.x1; x++) out.push({ a: 'x', x, z, r: side === 'front' ? 0 : 2 });
  } else {
    const x = side === 'right' ? b.x1 + 1 : b.x0;
    for (let z = b.z0; z <= b.z1; z++) out.push({ a: 'z', x, z, r: side === 'right' ? 0 : 2 });
  }
  return out;
}

/** Normalize an entry of a side list: string → {t}, null/undefined → plain wall, false → skip. */
function entryOf(s, fallback = 'wall') {
  if (s === false) return null;
  if (s === null || s === undefined) return { t: fallback };
  if (typeof s === 'string') return { t: s };
  return s;
}

/**
 * Wall ring around a footprint at level y. sides = { front, back, left, right } arrays (one entry
 * per edge, in edgesOf order). base = shared fields ({ m, c, k }).
 */
function walls(b, y, base, sides = {}) {
  const out = [];
  for (const side of ['front', 'right', 'back', 'left']) {
    const list = sides[side] || [];
    edgesOf(b, side).forEach((e, i) => {
      const en = entryOf(list[i]);
      if (en) out.push({ ...base, ...e, y, ...en });
    });
  }
  return out;
}

/** n consecutive edges along axis a starting at (x, z): railings, fences, hedges, beams. */
function run(t, a, x, z, n, y = 0, o = {}, skip = []) {
  const out = [];
  for (let i = 0; i < n; i++) {
    if (skip.includes(i)) continue;
    out.push({ t, a, x: a === 'x' ? x + i : x, z: a === 'z' ? z + i : z, y, r: 0, ...o });
  }
  return out;
}

/**
 * Slopes of a symmetric gable roof over footprint b at level y.
 *   ridge 'x': slopes face ±Z (rows along X); ridge 'z': slopes face ±X (gable ends front/back).
 *   The width across the slopes must be even; rows are stacked by h from the eaves (h0) up.
 */
function gableRoof(b, roof) {
  const { y, ridge = 'x', t = 'roof_slope', m, c, h0 = 0 } = roof;
  const rise = getDef(t)?.roof?.rise ?? 1;
  const out = [];
  if (ridge === 'x') {
    const half = (b.z1 - b.z0 + 1) / 2;
    for (let i = 0; i < half; i++) {
      for (let x = b.x0; x <= b.x1; x++) {
        out.push({ t, x, y, z: b.z0 + i, r: 0, h: h0 + i * rise, m, c });
        out.push({ t, x, y, z: b.z1 - i, r: 2, h: h0 + i * rise, m, c });
      }
    }
  } else {
    const half = (b.x1 - b.x0 + 1) / 2;
    for (let i = 0; i < half; i++) {
      for (let z = b.z0; z <= b.z1; z++) {
        out.push({ t, x: b.x0 + i, y, z, r: 1, h: h0 + i * rise, m, c });
        out.push({ t, x: b.x1 - i, y, z, r: 3, h: h0 + i * rise, m, c });
      }
    }
  }
  return out;
}

/**
 * Gable ends under a gableRoof (same box & roof spec). spec = { front, back } (ridge 'z') or
 * { left, right } (ridge 'x'): one entry per edge — a type, a record override, an ARRAY of entries for
 * several levels (e.g. a door at level 0 under a gable at level 1), or false. Entries default to
 * level roof.y; autoGable types get h / s / r exactly as builder.autoGable computes them (h counted
 * from their own level), other types become ordinary walls facing outward.
 */
function gableEnds(b, roof, spec = {}, base = {}) {
  const rise = getDef(roof.t || 'roof_slope')?.roof?.rise ?? 1;
  const ridge = roof.ridge || 'x';
  const out = [];
  for (const side of ridge === 'x' ? ['left', 'right'] : ['front', 'back']) {
    if (spec[side] === false) continue;
    const edges = edgesOf(b, side);
    const n = edges.length, half = n / 2;
    const list = spec[side] || [];
    edges.forEach((e, i) => {
      const low = i < half;
      const j = low ? i : n - 1 - i;                       // rows up from the eave
      const hs = 2 * roof.y + (roof.h0 || 0) + j * rise;   // roof base at this edge (half-steps)
      // autoGable: local +X points uphill.  ridge 'x' → roof r 0 (low half) / 2;  ridge 'z' → r 1 / 3
      const gr = ridge === 'x' ? (low ? 2 : 0) : (low ? 0 : 2);
      let entries = list[i] === undefined ? 'gable' : list[i];
      if (entries === false) return;
      if (!Array.isArray(entries)) entries = [entries];
      for (const raw of entries) {
        const en = entryOf(raw, 'gable');
        if (!en) continue;
        const def = getDef(en.t);
        const y = en.y ?? roof.y;
        if (def?.autoGable) out.push({ ...base, a: e.a, x: e.x, z: e.z, y, r: gr, h: hs - 2 * y, s: rise, ...en, y });
        else out.push({ ...base, a: e.a, x: e.x, z: e.z, y, r: e.r, ...en, y });
      }
    });
  }
  return out;
}

/**
 * A porch / deck along the FRONT (+Z) of a footprint: deck cells from z = b.z1 + 1 for `depth` rows,
 * railing round the open sides with a gap (and steps) at `steps`, and optionally posts at the given
 * front vertices with beams along the front and sides (to carry a porch roof).
 *   o = { depth = 1, deck = { m }, rail = { m, c } | null, steps: x, stepsMat, posts: [x…] | null, post: { m, c } }
 */
function porch(b, o) {
  const depth = o.depth || 1, z0 = b.z1 + 1, zf = z0 + depth, n = b.x1 - b.x0 + 1;
  const out = rect('deck', b.x0, b.x1, z0, zf - 1, 0, { m: 'deck', r: 1, ...(o.deck || {}) });
  if (o.posts) {
    for (const x of o.posts) out.push({ t: 'post', x, y: 0, z: zf, ...o.post });
    out.push(...run('beam', 'x', b.x0, zf, n, 0, o.post));
    out.push(...run('beam', 'z', b.x0, z0, depth, 0, o.post), ...run('beam', 'z', b.x1 + 1, z0, depth, 0, o.post));
  }
  if (o.rail) {
    const gap = o.steps === undefined ? [] : [o.steps - b.x0];
    out.push(...run('railing', 'x', b.x0, zf, n, 0, o.rail, gap));
    out.push(...run('railing', 'z', b.x0, z0, depth, 0, o.rail), ...run('railing', 'z', b.x1 + 1, z0, depth, 0, o.rail));
  }
  if (o.steps !== undefined) out.push(at('steps', o.steps, zf, { r: 2, m: o.stepsMat || 'wood' }));
  return out;
}

// ====================================================================== the houses

const COL = {
  white: '#f7f3ea', cream: '#efe3c8', barn: '#b4473a', oxblood: '#8e3b32', rust: '#c96a5a',
  sage: '#9cae6b', moss: '#6f8f5a', teal: '#4f7a6a', duck: '#7fa7a3', sky: '#9fc0d6', denim: '#5d7fa3',
  navy: '#2f4a66', walnut: '#7a4b3a', umber: '#4a3a2e', charcoal: '#2b2b2b', mustard: '#e9c46a',
  blush: '#e7b7c8', plum: '#6b5b8e', lilac: '#b9a3c9',
};

// ---------------------------------------------------------------- Tiny Garden Shed (tutorial)
function shed() {
  const B = { x0: -1, x1: 0, z0: -1, z1: 0 };
  const W = { m: 'boardBatten', c: COL.sage, k: COL.white };
  const roof = { y: 1, ridge: 'z', t: 'roof_slope', m: 'roofShingle' };
  return [
    ...rect('foundation', B.x0, B.x1, B.z0, B.z1, 0, { m: 'floorPine' }),
    ...walls(B, 0, W, {
      front: ['wall_door', 'wall_window_shutters'],
      right: [null, 'wall_window'],
    }),
    ...gableRoof(B, roof),
    ...gableEnds(B, roof, {}, W),
    at('path', -1, 1, { m: 'path' }),
    at('path', -1, 2, { m: 'path' }),
    at('flowers', 0, 1),
    at('wheelbarrow', 1, 1, { r: 1, m: 'paintedWood', c: COL.barn }),
    at('flowers', -2, 0),
  ];
}

// ---------------------------------------------------------------- A-Frame Cabin
function aframe() {
  const B = { x0: -2, x1: 1, z0: -3, z1: 1 };
  const roof = { y: 0, ridge: 'z', t: 'roof_steep', m: 'roofShingle' };
  const glass = { m: 'glass', k: COL.umber };
  const back = { m: 'shingleSiding', k: COL.umber };
  const P = [];
  P.push(...rect('foundation', B.x0, B.x1, B.z0, B.z1, 0, { m: 'floorPine' }));
  // walls only where the roof leaves a full storey: the two middle edges front & back
  P.push(
    { t: 'wall_door_glass', a: 'x', x: -1, y: 0, z: 2, r: 0, ...glass },
    { t: 'wall', a: 'x', x: 0, y: 0, z: 2, r: 0, ...glass },
    { t: 'wall_window', a: 'x', x: -1, y: 0, z: -3, r: 2, ...back },
    { t: 'wall', a: 'x', x: 0, y: 0, z: -3, r: 2, ...back },
  );
  // sleeping loft over the back two rows, a ladder up from the living room
  P.push(...rect('floor', -1, 0, -3, -2, 1, { m: 'floorPine' }));
  P.push({ t: 'ladder', x: 0, y: 0, z: -1, r: 2, m: 'wood' });
  P.push(...run('beam', 'x', -1, -1, 2, 0, { m: 'timber' }));
  // steep panels straight from the foundation to the ridge
  P.push(...gableRoof(B, roof));
  // glass front gable, shingled back gable with a round window
  P.push(...gableEnds(B, roof, {
    front: ['gable', [{ t: 'gable_window', y: 1 }], [{ t: 'gable_window', y: 1 }], 'gable'], back: false,
  }, glass));
  P.push(...gableEnds(B, roof, {
    front: false, back: ['gable', [{ t: 'gable_window', y: 1 }], [{ t: 'gable', y: 1 }], 'gable'],
  }, back));
  // stone chimney through the right slope; its hearth warms the living room
  P.push({ t: 'chimney', x: 1, y: 0, z: 0, r: 3, m: 'stone' });
  // a deck across the glass front
  P.push(...porch(B, { depth: 2, rail: { m: 'wood' }, steps: 0, stepsMat: 'deck' }));
  // furnishings
  P.push(
    { t: 'bed', x: -1, y: 0, z: -3, r: 0, m: 'wood', c: COL.teal },
    { t: 'nightstand', x: -2, y: 0, z: -3, r: 0, m: 'wood' },
    { t: 'kitchen', x: 0, y: 0, z: -3, r: 0, m: 'wood' },
    { t: 'barrel', x: 1, y: 0, z: -3, r: 0, m: 'wood' },
    { t: 'wood_stove', x: 0, y: 0, z: -2, r: 3 },           // its stovepipe meets the loft floor
    { t: 'table', x: -1, y: 0, z: -1, r: 0, m: 'wood' },
    { t: 'chair', x: -1, y: 0, z: -2, r: 0, m: 'wood' },
    { t: 'crate_stack', x: 1, y: 0, z: -2, r: 3, m: 'wood' },
    { t: 'armchair', x: -1, y: 0, z: 0, r: 1, c: COL.rust },
    { t: 'rug_round', x: 0, y: 0, z: 0, r: 0, c: COL.mustard },
    { t: 'cat', x: 0, y: 0, z: 1, r: 3, c: COL.umber },
    { t: 'plant_pot', x: -2, y: 0, z: 1, r: 0 },
    { t: 'rug', x: -1, y: 1, z: -3, r: 1, c: COL.teal },
    { t: 'dog_bed', x: 0, y: 1, z: -3, r: 0, c: COL.rust },
    { t: 'plant_pot', x: -1, y: 1, z: -2, r: 0 },
    { t: 'bench', x: -1, y: 0, z: 3, r: 0, m: 'wood' },
    { t: 'plant_pot', x: 1, y: 0, z: 3, r: 0 },
  );
  // the woods
  P.push(
    at('tree_pine', -5, -4), at('tree_pine', -4, -6), at('tree_pine', 4, -5), at('tree_pine', 5, -2),
    at('tree_pine', -5, 2), at('tree_birch', -6, -1), at('boulders', -4, 4), at('fire_pit', 3, 6),
    at('woodpile', 3, -1, { r: 1 }), at('bush', -3, 5),
  );
  return P;
}

// ---------------------------------------------------------------- Log Cabin
function logcabin() {
  const B = { x0: -2, x1: 1, z0: -3, z1: 0 };          // the house
  const R = { x0: -2, x1: 1, z0: -3, z1: 1 };          // the roof runs on over the porch
  const W = { m: 'log', k: COL.barn };
  const roof = { y: 1, ridge: 'z', t: 'roof_slope', m: 'roofShingle' };
  const logs = { m: 'log' };
  const P = [];
  P.push(...rect('foundation', B.x0, B.x1, B.z0, B.z1, 0, { m: 'floorOak' }));
  P.push(...walls(B, 0, W, {
    front: ['wall_window_shutters', 'wall_door', 'wall', 'wall_window_shutters'],
    right: ['wall_window_shutters', 'wall', 'wall', 'wall_window_shutters'],
    back: ['wall', 'wall_window_shutters', 'wall', 'wall'],
    left: ['wall', 'wall_window_shutters', 'wall', 'wall_window_shutters'],
  }));
  // covered front porch: log posts & beams carry the roof, which simply runs on over it
  P.push(...porch(B, { rail: { m: 'wood' }, steps: -1, posts: [-2, 0, 2], post: logs }));
  // gentle shingle roof, log gables front & back (the front one shelters under the porch roof)
  P.push(...gableRoof(R, roof));
  P.push(...gableEnds(B, roof, {
    front: ['gable', 'gable_window', 'gable', 'gable'],
    back: ['gable', 'gable', 'gable_window', 'gable'],
  }, W));
  // stone chimney rising through the right slope, hearth inside
  P.push({ t: 'chimney', x: 1, y: 0, z: -1, r: 3, m: 'stone' });
  // inside
  P.push(
    { t: 'bed', x: -2, y: 0, z: -3, r: 0, m: 'timber', c: COL.barn },
    { t: 'nightstand', x: -1, y: 0, z: -3, r: 0, m: 'timber' },
    { t: 'kitchen_range', x: 0, y: 0, z: -3, r: 0, m: 'wood' },
    { t: 'bookshelf', x: 1, y: 0, z: -3, r: 0, m: 'timber' },
    { t: 'table', x: -2, y: 0, z: -1, r: 0, m: 'wood' },
    { t: 'chair', x: -2, y: 0, z: 0, r: 2, m: 'wood' },
    { t: 'chair', x: -1, y: 0, z: -1, r: 3, m: 'wood' },
    { t: 'armchair', x: 0, y: 0, z: -1, r: 1, c: COL.moss },
    { t: 'rug', x: 0, y: 0, z: -2, r: 1, c: COL.barn },
    { t: 'cat', x: 1, y: 0, z: 0, r: 3, c: '#e8862f' },
    { t: 'rug_round', x: -1, y: 0, z: 0, r: 0, c: COL.mustard },
  );
  // porch & yard
  P.push(
    { t: 'rocking_chair', x: 0, y: 0, z: 1, r: 0, m: 'wood' },
    { t: 'barrel', x: 1, y: 0, z: 1, r: 0, m: 'wood' },
    at('woodpile', 2, -2, { r: 1 }),
    at('lamp_post', -2, 3),
    at('path', -1, 3, { m: 'path' }), at('path', -1, 4, { m: 'path' }),
    at('tree_pine', -5, -4), at('tree_pine', 4, -5), at('tree_pine', -4, -6), at('tree_pine', 5, 0),
    at('tree_oak', -5, 1), at('boulders', 3, 3), at('bush', -3, 2), at('flowers', 0, 3),
  );
  return P;
}

// ---------------------------------------------------------------- Farmhouse
function farmhouse() {
  const B = { x0: -2, x1: 2, z0: -3, z1: 0 };
  const W = { m: 'clapboard', c: COL.white, k: COL.navy };
  const door = { k: COL.teal };
  const roof = { y: 2, ridge: 'x', t: 'roof_slope', m: 'roofMetal', c: COL.barn };
  const trim = { m: 'trim', c: COL.white };
  const sh = 'wall_window_shutters';
  const P = [];
  P.push(...rect('foundation', B.x0, B.x1, B.z0, B.z1, 0, { m: 'floorOak' }));
  P.push(...walls(B, 0, W, {
    front: [sh, sh, { t: 'wall_door', ...door }, sh, sh],
    right: [sh, 'wall', sh, 'wall'],
    back: [sh, 'wall_window', { t: 'wall_door', ...door }, 'wall', sh],
    left: [sh, 'wall', 'wall', sh],
  }));
  // front porch: white columns, beams, railing, a low tin roof (below) and steps up the middle
  P.push(...porch(B, { rail: trim, steps: 0, posts: [-2, 0, 1, 3], post: trim }));
  // upper floor over every room, stairs along the left wall
  P.push({ t: 'stairs', x: -2, y: 0, z: -2, r: 2, m: 'wood' });
  P.push(...rect('floor', B.x0, B.x1, B.z0, B.z1, 1, { m: 'floorPine' }));
  P.push(...walls(B, 1, W, {
    front: [sh, sh, sh, sh, sh],
    right: [sh, 'wall', sh, 'wall'],
    back: ['wall_window', 'wall', 'wall_window', 'wall', 'wall_window'],
    left: [sh, 'wall', 'wall', sh],
  }));
  // red tin roof, white gables with little round windows
  P.push(...gableRoof(B, roof));
  P.push(...rect('roof_flat', B.x0, B.x1, 1, 1, 1, { m: 'roofMetal', c: COL.barn }));
  P.push(...gableEnds(B, roof, {
    left: ['gable', 'gable_window', 'gable_window', 'gable'],
    right: ['gable', 'gable_window', 'gable_window', 'gable'],
  }, W));
  // chimney: parlour fireplace below, bedroom hearth above, stack through the front slope
  P.push({ t: 'chimney', x: 2, y: 1, z: 0, r: 3, m: 'brick' });
  // ground floor: kitchen at the back, dining, parlour by the fire
  P.push(
    { t: 'fireplace', x: 2, y: 0, z: 0, r: 3 },
    { t: 'armchair', x: 1, y: 0, z: 0, r: 1, c: COL.rust },
    { t: 'rug', x: 1, y: 0, z: -1, r: 1, c: COL.denim },
    { t: 'grandfather_clock', x: -2, y: 0, z: -3, r: 0, m: 'timber' },
    { t: 'kitchen', x: -1, y: 0, z: -3, r: 0, m: 'paintedWood', c: COL.duck },
    { t: 'kitchen_range', x: 1, y: 0, z: -3, r: 0, m: 'paintedWood', c: COL.duck },
    { t: 'kitchen_counter', x: 2, y: 0, z: -3, r: 0, m: 'paintedWood', c: COL.duck },
    { t: 'table', x: -1, y: 0, z: -1, r: 0, m: 'wood' },
    { t: 'chair', x: -1, y: 0, z: 0, r: 2, m: 'paintedWood', c: COL.cream },
    { t: 'chair', x: 0, y: 0, z: -1, r: 3, m: 'paintedWood', c: COL.cream },
    { t: 'chair', x: -1, y: 0, z: -2, r: 0, m: 'paintedWood', c: COL.cream },
    { t: 'piano', x: -2, y: 0, z: 0, r: 1, m: 'timber' },
    { t: 'dog_bed', x: 2, y: 0, z: -1, r: 3, c: COL.barn },
  );
  // upstairs: bedroom, washstand & tub, a desk under the window
  P.push(
    { t: 'bed', x: 0, y: 1, z: -3, r: 0, m: 'trim', c: COL.denim },
    { t: 'nightstand', x: 1, y: 1, z: -3, r: 0, m: 'paintedWood', c: COL.cream },
    { t: 'wardrobe', x: -1, y: 1, z: -3, r: 0, m: 'paintedWood', c: COL.cream },
    { t: 'rug_round', x: 0, y: 1, z: -1, r: 0, c: COL.blush },
    { t: 'bathtub', x: 2, y: 1, z: -2, r: 3, c: COL.white },
    { t: 'washstand', x: 2, y: 1, z: -3, r: 0, m: 'paintedWood', c: COL.cream },
    { t: 'desk', x: -1, y: 1, z: 0, r: 2, m: 'wood' },
    { t: 'dresser', x: -2, y: 1, z: 0, r: 1, m: 'paintedWood', c: COL.cream },
    { t: 'cat', x: 1, y: 1, z: -1, r: 2, c: '#e8862f' },
  );
  // yard: picket fence with a gate, path, veggie garden, apple tree, mailbox
  P.push(...run('fence_picket', 'x', -4, 4, 9, 0, trim, [4]));
  P.push(...run('fence_picket', 'z', -4, 2, 2, 0, trim), ...run('fence_picket', 'z', 5, 2, 2, 0, trim));
  P.push(at('path', 0, 3, { m: 'brick' }), at('path', 0, 4, { m: 'brick' }), at('path', 0, 5, { m: 'brick' }));
  P.push(
    at('mailbox', 1, 4, { r: 0, c: COL.barn }),
    at('flowers', -2, 3), at('flowers', 2, 3), at('flowers', -1, 3), at('flowers', 1, 3),
    at('veggie_bed', 4, -3, { r: 1, m: 'wood' }), at('veggie_bed', 4, -2, { r: 1, m: 'wood' }), at('pumpkins', 4, -1),
    at('tree_apple', -5, -2), at('tree_oak', 6, -5), at('tree_birch', -6, 1),
    at('bush', -3, 3), at('bush', 3, 3),
  );
  return P;
}

